create extension if not exists pgcrypto;
create type public.user_role as enum ('admin');
create table public.profiles(id uuid primary key references auth.users on delete cascade, role user_role not null default 'admin', created_at timestamptz default now(), updated_at timestamptz default now());
create table public.business_settings(id uuid primary key default gen_random_uuid(), name text not null, phone text, whatsapp text, instagram text, address jsonb default '{}', location jsonb default '{}', description text, links jsonb default '{}', published boolean default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.business_hours(id uuid primary key default gen_random_uuid(), day_of_week smallint unique check(day_of_week between 0 and 6), opens time, closes time, closed boolean default false, updated_at timestamptz default now());
create table public.service_categories(id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, sort_order int default 0, active boolean default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.services(id uuid primary key default gen_random_uuid(), category_id uuid references public.service_categories on delete set null, name text not null, slug text unique not null, description text, image_url text, price numeric(10,2), duration text, featured boolean default false, active boolean default true, sort_order int default 0, icon text, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.product_categories(id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, sort_order int default 0, active boolean default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.products(id uuid primary key default gen_random_uuid(), category_id uuid references public.product_categories on delete set null, name text not null, slug text unique not null, description text, short_description text, price numeric(10,2), promotional_price numeric(10,2), brand text, featured boolean default false, active boolean default true, stock_status text default 'on_request' check(stock_status in ('available','on_request','unavailable')), created_at timestamptz default now(), updated_at timestamptz default now());
create table public.product_images(id uuid primary key default gen_random_uuid(), product_id uuid references public.products on delete cascade, url text not null, alt_text text, sort_order int default 0, created_at timestamptz default now());
create table public.reviews(id uuid primary key default gen_random_uuid(), author text not null, body text not null, rating smallint check(rating between 1 and 5), source text default 'Google', active boolean default true, sort_order int default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.gallery(id uuid primary key default gen_random_uuid(), url text not null, alt_text text not null, active boolean default true, sort_order int default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.site_sections(id uuid primary key default gen_random_uuid(), key text unique not null, content jsonb not null default '{}', active boolean default true, updated_at timestamptz default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
alter table profiles enable row level security; alter table business_settings enable row level security; alter table business_hours enable row level security; alter table service_categories enable row level security; alter table services enable row level security; alter table product_categories enable row level security; alter table products enable row level security; alter table product_images enable row level security; alter table reviews enable row level security; alter table gallery enable row level security; alter table site_sections enable row level security;
create policy "public business" on business_settings for select using(published); create policy "public hours" on business_hours for select using(true); create policy "public service categories" on service_categories for select using(active); create policy "public services" on services for select using(active); create policy "public product categories" on product_categories for select using(active); create policy "public products" on products for select using(active); create policy "public product images" on product_images for select using(exists(select 1 from products p where p.id=product_id and p.active)); create policy "public reviews" on reviews for select using(active); create policy "public gallery" on gallery for select using(active); create policy "public sections" on site_sections for select using(active);
do $$ declare t text; begin foreach t in array array['profiles','business_settings','business_hours','service_categories','services','product_categories','products','product_images','reviews','gallery','site_sections'] loop execute format('create policy "admin all" on public.%I for all using (public.is_admin()) with check (public.is_admin())',t); end loop; end $$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('products','products',true,5242880,array['image/jpeg','image/png','image/webp']),('services','services',true,5242880,array['image/jpeg','image/png','image/webp']),('gallery','gallery',true,5242880,array['image/jpeg','image/png','image/webp']),('site','site',true,5242880,array['image/jpeg','image/png','image/webp']);
create policy "public media" on storage.objects for select using(bucket_id in ('products','services','gallery','site')); create policy "admin media insert" on storage.objects for insert with check(bucket_id in ('products','services','gallery','site') and public.is_admin()); create policy "admin media update" on storage.objects for update using(public.is_admin()); create policy "admin media delete" on storage.objects for delete using(public.is_admin());
